import { useMemo, useState, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate } from "@tanstack/react-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from "recharts";
import { Activity, Pencil, Archive, ArrowRightLeft, Bell, Boxes, Building2, CalendarClock, CheckCircle2, ChevronDown, ChevronRight, CircleDollarSign, ClipboardCheck, Clock3, Download, FileSpreadsheet, Filter, History, LayoutDashboard, LoaderCircle, LogOut, Menu, MoreHorizontal, PackagePlus, PanelLeftClose, PanelLeftOpen, QrCode, Search, Settings, ShieldCheck, Upload, UserRound, Users, Wrench, X } from "lucide-react";
import { toast } from "sonner";
import { AssetForm } from "@/components/asset360/asset-form";
import { AssetImport } from "@/components/asset360/asset-import";
import { LabelDialog } from "@/components/asset360/label-dialog";
import { bootstrapWorkspace, createTransfer, getWorkspaceData, processTransfer } from "@/lib/asset360.functions";
import { exportDashboardCsv, exportDashboardPdf, type DashboardReport } from "@/lib/dashboard-export";
import { downloadAssetTemplate } from "@/lib/asset-import";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";

export type WorkspaceData = Exclude<Awaited<ReturnType<typeof getWorkspaceData>>, { needsOnboarding: true }>;
type Asset = WorkspaceData["assets"][number];
const money = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const activeStatuses = new Set(["active", "assigned", "in_stock"]);
const assetStartDate = (asset: Asset) => asset.capitalization_date ?? asset.purchase_date ?? asset.created_at;
const assetAgeMonths = (asset: Asset) => Math.max(0, Math.floor((Date.now() - new Date(assetStartDate(asset)).getTime()) / 2629800000));
const formatAge = (months: number) => months < 12 ? `${months} mo` : `${Math.floor(months / 12)} yr${Math.floor(months / 12)===1?"":"s"} ${months % 12} mo`;
const formatDate = (value: string) => new Intl.DateTimeFormat("en-IN", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value));
const nav = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard }, { id: "assets", label: "Assets", icon: Boxes, count: 54 }, { id: "transfers", label: "Transfers", icon: ArrowRightLeft, count: 3 }, { id: "maintenance", label: "Maintenance", icon: Wrench }, { id: "verification", label: "Verification", icon: ClipboardCheck },
  { id: "categories", label: "Categories", icon: Archive }, { id: "locations", label: "Locations", icon: Building2 }, { id: "employees", label: "Employees", icon: Users }, { id: "reports", label: "Reports", icon: FileSpreadsheet }, { id: "audit", label: "Audit trail", icon: History }, { id: "settings", label: "Settings", icon: Settings },
];
const pageCopy: Record<string, [string, string]> = { dashboard: ["Dashboard", "Your asset operations at a glance."], assets: ["Asset master", "Search, filter, and manage every registered asset."], transfers: ["Asset transfers", "Track handovers and approval status."], maintenance: ["Maintenance", "Plan service and reduce avoidable downtime."], verification: ["Verification", "Reconcile physical assets with your register."], categories: ["Asset categories", "Manage identification prefixes and classes."], locations: ["Locations", "Navigate your company’s physical hierarchy."], employees: ["Employees", "Manage custodians and ownership."], reports: ["Reports", "Export operational insights for review."], audit: ["Audit trail", "Review immutable activity across the workspace."], settings: ["Settings", "Configure your organization and integrations."] };

export function Workspace() {
  const query = useQuery({ queryKey: ["workspace"], queryFn: () => getWorkspaceData() });
  const [active, setActive] = useState("dashboard"); const [collapsed, setCollapsed] = useState(false); const [mobileOpen, setMobileOpen] = useState(false);
  const [assetDialog, setAssetDialog] = useState(false); const [importOpen, setImportOpen] = useState(false); const [editingAsset, setEditingAsset] = useState<Asset | null>(null); const [transferDialog, setTransferDialog] = useState(false); const [search, setSearch] = useState(""); const [selectedAsset, setSelectedAsset] = useState<Asset | null>(null);
  if (query.isLoading) return <LoadingScreen />;
  if (query.error) return <ErrorScreen message={query.error.message} retry={() => query.refetch()} />;
  if (query.data?.needsOnboarding) return <Onboarding />;
  const data = query.data as WorkspaceData;
  const title = pageCopy[active] ?? pageCopy["dashboard"] ?? ["Dashboard", "Your asset operations at a glance."];
  const filtered = data.assets.filter((asset) => [asset.asset_id, asset.name, asset.serial_number, asset.manufacturer, asset.model, asset.plant, asset.company_code].some((field) => field?.toLowerCase().includes(search.toLowerCase())));
  return <div className="app-backdrop min-h-screen">
    <Sidebar data={data} active={active} setActive={(id) => {setActive(id);setMobileOpen(false)}} collapsed={collapsed} setCollapsed={setCollapsed} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}/>
    <div className={`min-h-screen transition-[margin] duration-200 ${collapsed ? "lg:ml-[76px]" : "lg:ml-[248px]"}`}>
      <Topbar data={data} assets={data.assets} onMenu={() => setMobileOpen(true)} onSelectAsset={(asset) => { setSelectedAsset(asset); setActive("assets"); }} />
      <main className="mx-auto max-w-[1600px] px-4 pb-24 pt-6 sm:px-6 lg:px-8 lg:pb-10">
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Operations center</p><h1 className="font-display text-2xl font-bold tracking-tight sm:text-3xl">{importOpen ? "Import assets" : assetDialog ? editingAsset ? "Edit asset" : "Add asset" : title[0]}</h1>{!assetDialog && !importOpen && <p className="mt-1 text-sm text-muted-foreground">{title[1]}</p>}</div>{!assetDialog && !importOpen && <PageActions active={active} onImport={()=>setImportOpen(true)} setAssetDialog={()=>{setEditingAsset(null);setActive("assets");setAssetDialog(true)}} data={data} assets={data.assets}/>}</div>
        {importOpen && <AssetImport data={data} onClose={()=>setImportOpen(false)}/>}
        {assetDialog && <AssetForm key={editingAsset?.id ?? "new"} data={data} asset={editingAsset} onClose={()=>{setAssetDialog(false);setEditingAsset(null)}}/>}
        <div hidden={assetDialog || importOpen}>{active === "dashboard" ? <Dashboard data={data} setActive={setActive} onAsset={setSelectedAsset}/> : active === "assets" ? <Assets data={data} assets={filtered} search={search} setSearch={setSearch} onAsset={setSelectedAsset} setAssetDialog={setAssetDialog} onEdit={asset=>{setEditingAsset(asset);setAssetDialog(true)}}/> : active === "transfers" ? <Transfers data={data} onNew={()=>setTransferDialog(true)}/> : <ModulePage id={active} data={data}/>}</div> 
      </main>
    </div>
    <MobileNav active={active} setActive={setActive}/>
    <CreateTransferDialog open={transferDialog} setOpen={setTransferDialog} data={data}/>
    <AssetDetail asset={selectedAsset} onClose={() => setSelectedAsset(null)} onEdit={asset=>{setSelectedAsset(null);setEditingAsset(asset);setActive("assets");setAssetDialog(true)}}/>
  </div>;
}

function LoadingScreen(){return <main className="app-backdrop grid min-h-screen place-items-center"><div className="glass-panel rounded-2xl p-8 text-center"><LoaderCircle className="mx-auto size-8 animate-spin text-primary"/><p className="mt-3 text-sm font-medium">Preparing your workspace…</p></div></main>}
function ErrorScreen({message,retry}:{message:string;retry:()=>void}){return <main className="app-backdrop grid min-h-screen place-items-center px-4"><div className="glass-panel max-w-md rounded-2xl p-8 text-center"><ShieldCheck className="mx-auto size-9 text-destructive"/><h1 className="mt-3 font-display text-xl font-bold">Workspace unavailable</h1><p className="my-4 text-sm text-muted-foreground">{message}</p><Button onClick={retry}>Try again</Button></div></main>}
function Onboarding(){const queryClient=useQueryClient();const [name,setName]=useState("");const mutation=useMutation({mutationFn:()=>bootstrapWorkspace({data:{fullName:name}}),onSuccess:()=>queryClient.invalidateQueries({queryKey:["workspace"]}),onError:(e)=>toast.error(e.message)});return <main className="app-backdrop grid min-h-screen place-items-center px-4"><form onSubmit={(e)=>{e.preventDefault();mutation.mutate()}} className="glass-panel w-full max-w-lg rounded-2xl p-8"><div className="mb-5 grid size-12 place-items-center rounded-xl bg-primary text-white shadow-brand"><Building2/></div><h1 className="font-display text-2xl font-bold">Welcome to Asset360</h1><p className="mt-2 text-sm text-muted-foreground">We’ll create a secure demo workspace with realistic categories, locations, employees, and assets.</p><div className="my-6"><Label htmlFor="onboard-name">Your full name</Label><Input id="onboard-name" className="mt-2 h-11 bg-glass-strong" value={name} onChange={e=>setName(e.target.value)} minLength={2} maxLength={100} required autoFocus/></div><Button variant="hero" size="lg" className="w-full" disabled={mutation.isPending}>{mutation.isPending&&<LoaderCircle className="animate-spin"/>}Create secure workspace</Button></form></main>}

function Sidebar({data,active,setActive,collapsed,setCollapsed,mobileOpen,setMobileOpen}:{data:WorkspaceData;active:string;setActive:(s:string)=>void;collapsed:boolean;setCollapsed:(b:boolean)=>void;mobileOpen:boolean;setMobileOpen:(b:boolean)=>void}){
 const content=<><div className="flex h-20 items-center gap-3 px-4"><div className="grid size-10 shrink-0 place-items-center rounded-xl bg-primary font-display text-lg font-bold text-white shadow-brand">A</div>{!collapsed&&<div><p className="font-display text-sm font-bold">Sharvi Asset360</p><p className="text-[9px] font-semibold uppercase tracking-[.16em] text-muted-foreground">Asset lifecycle</p></div>}</div><nav className="flex-1 space-y-1 overflow-y-auto px-3 pb-4">{nav.map((item,index)=><div key={item.id}>{[5,8].includes(index)&&!collapsed&&<p className="mb-2 mt-5 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">{index===5?"Master data":"Control"}</p>}<button onClick={()=>setActive(item.id)} title={collapsed?item.label:undefined} className={`group flex h-10 w-full items-center gap-3 rounded-xl px-3 text-left text-sm font-medium transition ${active===item.id?"bg-primary text-white shadow-brand":"text-muted-foreground hover:bg-white/50 hover:text-foreground"}`}><item.icon className="size-[18px] shrink-0"/>{!collapsed&&<><span className="flex-1 truncate">{item.label}</span>{item.count&&<span className={`rounded-full px-2 py-0.5 text-[10px] ${active===item.id?"bg-white/18":"bg-primary/10 text-primary"}`}>{item.count}</span>}</>}</button></div>)}</nav><div className="p-3"><div className={`rounded-xl bg-white/35 p-3 ${collapsed?"grid place-items-center":""}`}><ShieldCheck className="size-5 text-success"/>{!collapsed&&<><p className="mt-2 text-xs font-semibold">Secure workspace</p><p className="mt-0.5 text-[10px] text-muted-foreground">Tenant isolated · RLS active</p></>}</div></div></>;
 return <><aside className={`glass-strong fixed inset-y-0 left-0 z-40 hidden border-y-0 border-l-0 transition-[width] lg:flex lg:flex-col ${collapsed?"w-[76px]":"w-[248px]"}`}>{content}<button aria-label="Toggle sidebar" onClick={()=>setCollapsed(!collapsed)} className="absolute -right-3 top-24 grid size-7 place-items-center rounded-full border bg-background shadow"><ChevronRight className={`size-4 transition ${collapsed?"":"rotate-180"}`}/></button></aside><Sheet open={mobileOpen} onOpenChange={setMobileOpen}><SheetContent side="left" className="app-backdrop w-[280px] p-0"><SheetHeader className="sr-only"><SheetTitle>Navigation</SheetTitle></SheetHeader><div className="flex h-full flex-col">{content}</div></SheetContent></Sheet></>;
}
function Topbar({data,assets,onMenu,onSelectAsset}:{data:WorkspaceData;assets:Asset[];onMenu:()=>void;onSelectAsset:(a:Asset)=>void}){const navigate=useNavigate();const [search,setSearch]=useState("");const matches=search.length>1?assets.filter(a=>`${a.asset_id} ${a.name} ${a.serial_number}`.toLowerCase().includes(search.toLowerCase())).slice(0,5):[];async function logout(){await supabase.auth.signOut();await navigate({to:"/auth"})}return <header className="sticky top-0 z-30 flex h-16 items-center gap-3 border-b border-white/50 bg-background/65 px-4 backdrop-blur-2xl sm:px-6 lg:px-8"><Button variant="ghost" size="icon" className="lg:hidden" onClick={onMenu}><Menu/></Button><div className="relative hidden max-w-xl flex-1 sm:block"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground"/><Input className="h-10 rounded-xl bg-white/60 pl-9" placeholder="Search assets, serial numbers, employees…" value={search} onChange={e=>setSearch(e.target.value)}/>{matches.length>0&&<div className="glass-strong absolute top-12 w-full rounded-xl p-2 shadow-glass">{matches.map(asset=><button key={asset.id} onClick={()=>{onSelectAsset(asset);setSearch("")}} className="flex w-full items-center justify-between rounded-lg p-2 text-left text-sm hover:bg-primary/10"><span><b>{asset.asset_id}</b> · {asset.name}</span><ChevronRight className="size-4"/></button>)}</div>}</div><div className="ml-auto hidden items-center gap-2 text-xs font-medium text-success sm:flex"><span className="size-2 rounded-full bg-success"/> All systems operational</div><Button variant="ghost" size="icon" className="relative"><Bell className="size-5"/><span className="absolute right-2 top-2 size-2 rounded-full bg-destructive ring-2 ring-background"/></Button><DropdownMenu><DropdownMenuTrigger asChild><button className="flex items-center gap-2 rounded-xl p-1.5 hover:bg-white/50"><span className="grid size-8 place-items-center rounded-lg bg-primary/10 text-primary"><UserRound className="size-4"/></span><span className="hidden text-left lg:block"><b className="block max-w-32 truncate text-xs">{data.profile?.full_name??"Asset Manager"}</b><span className="block text-[10px] text-muted-foreground">{data.role.replaceAll("_"," ")}</span></span><ChevronDown className="hidden size-4 text-muted-foreground lg:block"/></button></DropdownMenuTrigger><DropdownMenuContent align="end" className="w-56"><DropdownMenuLabel>{data.organization?.name}</DropdownMenuLabel><DropdownMenuSeparator/><DropdownMenuItem><UserRound/>Profile</DropdownMenuItem><DropdownMenuItem><Settings/>Settings</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem onClick={logout} className="text-destructive"><LogOut/>Sign out</DropdownMenuItem></DropdownMenuContent></DropdownMenu></header>}

function Dashboard({data,setActive,onAsset}:{data:WorkspaceData;setActive:(s:string)=>void;onAsset:(a:Asset)=>void}){
  const [category,setCategory]=useState("all");
  const [location,setLocation]=useState("all");
  const [status,setStatus]=useState("all");
  const [age,setAge]=useState("all");
  const filteredAssets=useMemo(()=>data.assets.filter(asset=>{
    const months=assetAgeMonths(asset);
    const statusMatches=status==="all"||(status==="active"?activeStatuses.has(asset.status):!activeStatuses.has(asset.status));
    const ageMatches=age==="all"||(age==="under-1"&&months<12)||(age==="1-3"&&months>=12&&months<36)||(age==="3-5"&&months>=36&&months<60)||(age==="5-plus"&&months>=60);
    return (category==="all"||asset.asset_categories?.name===category)&&(location==="all"||asset.locations?.name===location)&&statusMatches&&ageMatches;
  }),[age,category,data.assets,location,status]);
  const hasFilters=category!=="all"||location!=="all"||status!=="all"||age!=="all";
  const total=filteredAssets.length;
  const purchaseCost=filteredAssets.reduce((n,a)=>n+Number(a.purchase_value??0),0);
  const currentValue=filteredAssets.reduce((n,a)=>n+Number(a.current_value??0),0);
  const active=filteredAssets.filter(a=>activeStatuses.has(a.status)).length;
  const inactive=total-active;
  const maintenance=filteredAssets.filter(a=>["under_maintenance","under_repair"].includes(a.status)).length;
  const warranties=filteredAssets.filter(a=>a.warranty_end&&new Date(a.warranty_end)<new Date(Date.now()+90*86400000)&&new Date(a.warranty_end)>=new Date()).length;
  const filteredAssetCodes=new Set(filteredAssets.map(asset=>asset.asset_id));
  const verifiedCount=new Set(data.verifications.filter(item=>filteredAssetCodes.has(item.assets.asset_id)).map(item=>item.assets.asset_id)).size;
  const ages=filteredAssets.map(assetAgeMonths);
  const averageAge=ages.length?Math.round(ages.reduce((sum,item)=>sum+item,0)/ages.length):0;
  const ageData=[{name:"< 1 year",value:ages.filter(x=>x<12).length},{name:"1–3 years",value:ages.filter(x=>x>=12&&x<36).length},{name:"3–5 years",value:ages.filter(x=>x>=36&&x<60).length},{name:"5+ years",value:ages.filter(x=>x>=60).length}];
  const statusData=[{name:"Active",value:active,fill:"var(--success)"},{name:"Inactive",value:inactive,fill:"var(--destructive)"}];
  const resetFilters=()=>{setCategory("all");setLocation("all");setStatus("all");setAge("all")};
  const report=():DashboardReport=>{
    const selectedFilters=[category==="all"?"All categories":`Category: ${category}`,location==="all"?"All locations":`Location: ${location}`,status==="all"?"All statuses":`Status: ${pretty(status)}`,age==="all"?"All installation ages":`Installation age: ${age==="under-1"?"Under 1 year":age==="5-plus"?"5+ years":`${age} years`}`];
    return {organization:data.organization?.name??"Organization",generatedAt:new Intl.DateTimeFormat("en-IN",{dateStyle:"medium",timeStyle:"short"}).format(new Date()),filters:selectedFilters,metrics:[["Total assets",String(total)],["Total acquisition cost",money.format(purchaseCost)],["Current value",money.format(currentValue)],["Average equipment life",formatAge(averageAge)],["Active / inactive",`${active} / ${inactive}`]],ageProfile:ageData.map(item=>[item.name,item.value]),statusProfile:statusData.map(item=>[item.name,item.value]),attention:[["Inactive assets",inactive],["Maintenance due",maintenance],["Warranties expiring",warranties],["Pending verification",Math.max(0,total-verifiedCount)]],assets:filteredAssets.map(asset=>[asset.asset_id,asset.name,asset.asset_categories?.name??"—",asset.locations?.name??"—",asset.employees?.full_name??"—",formatDate(assetStartDate(asset)),formatAge(assetAgeMonths(asset)),pretty(asset.status),money.format(Number(asset.purchase_value??0)),money.format(Number(asset.current_value??0))])};
  };
  const runExport=(format:"csv"|"pdf")=>{if(!total){toast.error("No filtered assets to export");return}const current=report();if(format==="csv"){exportDashboardCsv(current);toast.success("Filtered dashboard CSV exported");return}exportDashboardPdf(current).then(()=>toast.success("Filtered dashboard PDF exported")).catch(()=>toast.error("Could not create the PDF report"))};
  return <div className="space-y-5 soft-enter">
    <section className="glass-panel p-4 sm:p-5" aria-label="Dashboard filters">
      <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3 sm:flex sm:justify-between">
        <div className="flex min-w-0 items-center gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><Filter className="size-4"/></span><div className="min-w-0"><h2 className="truncate font-display text-sm font-bold">Dashboard filters</h2><p className="truncate text-xs text-muted-foreground">Showing {total} of {data.assets.length} assets</p></div></div>
        <div className="flex items-center gap-1"><DropdownMenu><DropdownMenuTrigger asChild><Button variant="glass" size="sm" disabled={!total}><Download className="size-4"/>Export</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel>Filtered dashboard</DropdownMenuLabel><DropdownMenuItem onClick={()=>runExport("csv")}><FileSpreadsheet/>Export CSV</DropdownMenuItem><DropdownMenuItem onClick={()=>runExport("pdf")}><Download/>Export PDF</DropdownMenuItem></DropdownMenuContent></DropdownMenu><Button variant="ghost" size="sm" onClick={resetFilters} disabled={!hasFilters}><X className="size-4"/>Reset</Button></div>
      </div>
      <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <Select value={category} onValueChange={setCategory}><SelectTrigger className="w-full bg-glass-strong" aria-label="Filter by category"><SelectValue placeholder="All categories"/></SelectTrigger><SelectContent><SelectItem value="all">All categories</SelectItem>{data.categories.map(item=><SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select>
        <Select value={location} onValueChange={setLocation}><SelectTrigger className="w-full bg-glass-strong" aria-label="Filter by location"><SelectValue placeholder="All locations"/></SelectTrigger><SelectContent><SelectItem value="all">All locations</SelectItem>{data.locations.map(item=><SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select>
        <Select value={status} onValueChange={setStatus}><SelectTrigger className="w-full bg-glass-strong" aria-label="Filter by status"><SelectValue placeholder="All statuses"/></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem><SelectItem value="active">Active</SelectItem><SelectItem value="inactive">Inactive</SelectItem></SelectContent></Select>
        <Select value={age} onValueChange={setAge}><SelectTrigger className="w-full bg-glass-strong" aria-label="Filter by installation age"><SelectValue placeholder="All installation ages"/></SelectTrigger><SelectContent><SelectItem value="all">All installation ages</SelectItem><SelectItem value="under-1">Under 1 year</SelectItem><SelectItem value="1-3">1–3 years</SelectItem><SelectItem value="3-5">3–5 years</SelectItem><SelectItem value="5-plus">5+ years</SelectItem></SelectContent></Select>
      </div>
    </section>
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Kpi label="Total assets" value={total.toLocaleString()} delta={hasFilters?"Matching selected filters":"Registered equipment"} icon={Boxes} tone="primary"/><Kpi label="Total acquisition cost" value={money.format(purchaseCost)} delta="Original purchase value" icon={CircleDollarSign} tone="info"/><Kpi label="Current value" value={money.format(currentValue)} delta={`${purchaseCost?Math.round(currentValue/purchaseCost*100):0}% of acquisition cost`} icon={CircleDollarSign} tone="success"/><Kpi label="Average equipment life" value={formatAge(averageAge)} delta="From installation date" icon={Clock3} tone="warning"/><Kpi label="Active / inactive" value={`${active} / ${inactive}`} delta={`${Math.round(active/Math.max(total,1)*100)}% currently active`} icon={Activity} tone="success"/></section>
    <section className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><div className="glass-panel rounded-2xl p-5"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-3"><div className="min-w-0"><h2 className="truncate font-display font-bold">Equipment life profile</h2><p className="mt-1 text-xs text-muted-foreground">Age from installation date to today</p></div><Badge variant="outline" className="shrink-0 bg-white/50">Average {formatAge(averageAge)}</Badge></div><div className="mt-4 h-[270px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={ageData}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={11}/><YAxis allowDecimals={false} axisLine={false} tickLine={false} fontSize={11}/><ChartTooltip/><Bar dataKey="value" fill="var(--primary)" radius={[7,7,0,0]} name="Assets"/></BarChart></ResponsiveContainer></div></div><div className="glass-panel rounded-2xl p-5"><h2 className="font-display font-bold">Current status</h2><p className="mt-1 text-xs text-muted-foreground">Active and inactive equipment</p><div className="relative h-[190px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={statusData} dataKey="value" innerRadius={56} outerRadius={78} paddingAngle={4}>{statusData.map(x=><Cell key={x.name} fill={x.fill}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer><div className="pointer-events-none absolute inset-0 grid place-items-center text-center"><div><b className="font-display text-2xl">{total}</b><span className="block text-[10px] text-muted-foreground">ASSETS</span></div></div></div><div className="space-y-3">{statusData.map(x=><div className="flex items-center gap-3 text-sm" key={x.name}><span className={`size-2.5 rounded-full ${x.name==="Active"?"bg-success":"bg-destructive"}`}/><span className="text-muted-foreground">{x.name}</span><b className="ml-auto">{x.value}</b><span className="w-10 text-right text-xs text-muted-foreground">{Math.round(x.value/Math.max(total,1)*100)}%</span></div>)}</div></div></section>
    <section className="grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><div className="glass-panel overflow-hidden rounded-2xl"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3 p-5"><div className="min-w-0"><h2 className="truncate font-display font-bold">Recent assets</h2><p className="mt-1 truncate text-xs text-muted-foreground">Installation age and latest status</p></div><Button variant="ghost" size="sm" onClick={()=>setActive("assets")}>View all <ChevronRight/></Button></div>{total?<AssetTable assets={filteredAssets.slice(0,6)} onAsset={onAsset}/>:<div className="grid min-h-48 place-items-center px-5 pb-5 text-center"><div><Filter className="mx-auto size-7 text-muted-foreground"/><p className="mt-3 text-sm font-semibold">No assets match these filters</p><Button variant="ghost" size="sm" className="mt-2" onClick={resetFilters}>Clear filters</Button></div></div>}</div><div className="glass-panel rounded-2xl p-5"><h2 className="font-display font-bold">Needs attention</h2><p className="mt-1 text-xs text-muted-foreground">Current lifecycle exceptions</p><div className="mt-5 space-y-4"><CareRow icon={Activity} label="Inactive assets" value={inactive} color="destructive"/><CareRow icon={Wrench} label="Maintenance due" value={maintenance} color="warning"/><CareRow icon={CalendarClock} label="Warranties expiring" value={warranties} color="destructive"/><CareRow icon={ClipboardCheck} label="Pending verification" value={Math.max(0,total-verifiedCount)} color="primary"/></div><Button variant="glass" className="mt-5 w-full" onClick={()=>setActive("assets")}>Review asset register</Button></div></section>
  </div>
}
function Kpi({label,value,delta,icon:Icon,tone}:{label:string;value:string;delta:string;icon:any;tone:string}){return <div className="glass-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mt-2 font-display text-2xl font-bold">{value}</p></div><div className={`grid size-10 place-items-center rounded-xl bg-${tone}/10 text-${tone}`}><Icon className="size-5"/></div></div><p className="mt-3 text-[11px] font-medium text-muted-foreground"><span className="text-success">↗</span> {delta}</p></div>}
function CareRow({icon:Icon,label,value,color}:{icon:any;label:string;value:number;color:string}){return <div className="flex items-center gap-3"><div className={`grid size-9 place-items-center rounded-lg bg-${color}/10 text-${color}`}><Icon className="size-4"/></div><span className="flex-1 text-sm text-muted-foreground">{label}</span><b>{value}</b></div>}

function Assets({data,assets,search,setSearch,onAsset,setAssetDialog,onEdit}:{data:WorkspaceData;assets:Asset[];search:string;setSearch:(s:string)=>void;onAsset:(a:Asset)=>void;setAssetDialog:(b:boolean)=>void;onEdit:(a:Asset)=>void}){
  const [selected,setSelected]=useState<string[]>([]);const [labelsOpen,setLabelsOpen]=useState(false);
  const [category,setCategory]=useState("all");const [location,setLocation]=useState("all");const [plant,setPlant]=useState("all");const [companyCode,setCompanyCode]=useState("all");const [status,setStatus]=useState("all");const [age,setAge]=useState("all");
  const plants=useMemo(()=>Array.from(new Set(data.assets.map(a=>a.plant).filter((value):value is string=>Boolean(value)))).sort(),[data.assets]);
  const companyCodes=useMemo(()=>Array.from(new Set(data.assets.map(a=>a.company_code).filter((value):value is string=>Boolean(value)))).sort(),[data.assets]);
  const shown=assets.filter(asset=>{const months=assetAgeMonths(asset);const ageMatches=age==="all"||(age==="under-1"&&months<12)||(age==="1-3"&&months>=12&&months<36)||(age==="3-5"&&months>=36&&months<60)||(age==="5-plus"&&months>=60);return (category==="all"||asset.asset_categories?.name===category)&&(location==="all"||asset.locations?.name===location)&&(plant==="all"||asset.plant===plant)&&(companyCode==="all"||asset.company_code===companyCode)&&(status==="all"||asset.status===status)&&ageMatches});
  const hasFilters=Boolean(search)||[category,location,plant,companyCode,status,age].some(value=>value!=="all");
  const reset=()=>{setSearch("");setCategory("all");setLocation("all");setPlant("all");setCompanyCode("all");setStatus("all");setAge("all")};
  const labelAssets=shown.filter(asset=>selected.includes(asset.id));
  return <><LabelDialog open={labelsOpen} onOpenChange={setLabelsOpen} assets={labelAssets} organization={data.organization?.name??"Sharvi Asset360"}/><div className="overflow-hidden rounded-lg border border-glass-border bg-glass soft-enter"><div className="border-b border-glass-border p-4"><div className="flex flex-col gap-3 lg:flex-row lg:items-center"><div className="relative min-w-64 flex-1"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground"/><Input className="h-10 bg-white/60 pl-9" placeholder="Search ID, asset, serial, plant, company code…" value={search} onChange={e=>setSearch(e.target.value)}/></div><Button variant="ghost" onClick={reset} disabled={!hasFilters}><X/>Reset</Button><Button variant="outline" onClick={()=>setLabelsOpen(true)} disabled={!labelAssets.length}><QrCode/>QR labels ({labelAssets.length})</Button></div><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6"><AssetFilter value={category} setValue={setCategory} label="All categories" options={data.categories.map(x=>x.name)}/><AssetFilter value={location} setValue={setLocation} label="All locations" options={data.locations.map(x=>x.name)}/><AssetFilter value={plant} setValue={setPlant} label="All plants" options={plants}/><AssetFilter value={companyCode} setValue={setCompanyCode} label="All company codes" options={companyCodes}/><AssetFilter value={status} setValue={setStatus} label="All statuses" options={["active","assigned","in_stock","under_maintenance","under_repair","missing","damaged","retired","disposed"]}/><Select value={age} onValueChange={setAge}><SelectTrigger className="w-full bg-white/60" aria-label="Filter by installation age"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All ages</SelectItem><SelectItem value="under-1">Under 1 year</SelectItem><SelectItem value="1-3">1–3 years</SelectItem><SelectItem value="3-5">3–5 years</SelectItem><SelectItem value="5-plus">5+ years</SelectItem></SelectContent></Select></div></div><AssetTable assets={shown} onAsset={onAsset} onEdit={onEdit} selected={selected} setSelected={setSelected}/><div className="flex items-center justify-between border-t border-white/60 p-4 text-xs text-muted-foreground"><span>Showing {shown.length} of {data.assets.length} assets</span><span>{hasFilters?"Filtered register":"Live register"}</span></div></div></>}
function AssetFilter({value,setValue,label,options}:{value:string;setValue:(value:string)=>void;label:string;options:string[]}){return <Select value={value} onValueChange={setValue}><SelectTrigger className="w-full bg-white/60" aria-label={label}><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">{label}</SelectItem>{options.map(option=><SelectItem key={option} value={option}>{pretty(option)}</SelectItem>)}</SelectContent></Select>}
function AssetTable({assets,onAsset,selected,setSelected,onEdit}:{assets:Asset[];onAsset:(a:Asset)=>void;selected?:string[];setSelected?:(ids:string[])=>void;onEdit?:(a:Asset)=>void}){return <div className="overflow-x-auto"><table className="w-full min-w-[1500px] text-left text-sm"><thead className="bg-white/25 text-[10px] uppercase tracking-wider text-muted-foreground"><tr>{setSelected&&<th className="px-4 py-3"><input type="checkbox" aria-label="Select all filtered assets" className="size-4 accent-primary" checked={assets.length>0&&assets.every(asset=>selected?.includes(asset.id))} onChange={event=>setSelected(event.target.checked?Array.from(new Set([...(selected??[]),...assets.map(asset=>asset.id)])):(selected??[]).filter(id=>!assets.some(asset=>asset.id===id)))}/></th>}{["Asset ID","Asset","Serial number","Plant","Company code","Category","Location","Installed","Age","Status","Acquisition value","Book value",""].map(x=><th key={x} className="px-4 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{assets.map(asset=><tr key={asset.id} onClick={()=>onAsset(asset)} className="cursor-pointer border-t border-white/50 hover:bg-white/35"><>{setSelected&&<td className="px-4 py-3" onClick={event=>event.stopPropagation()}><input type="checkbox" aria-label={`Select ${asset.asset_id}`} className="size-4 accent-primary" checked={selected?.includes(asset.id)??false} onChange={event=>setSelected(event.target.checked?[...(selected??[]),asset.id]:(selected??[]).filter(id=>id!==asset.id))}/></td>}<td className="px-4 py-3 font-mono text-xs font-semibold text-primary"><Button variant="link" className="h-auto p-0 font-mono text-xs" onClick={event=>{event.stopPropagation();onAsset(asset)}}>{asset.asset_id}</Button></td></><td className="px-4 py-3"><b className="block text-xs">{asset.name}</b><span className="text-[10px] text-muted-foreground">{asset.manufacturer} {asset.model}</span></td><td className="px-4 py-3 font-mono text-xs text-muted-foreground">{asset.serial_number??"—"}</td><td className="px-4 py-3 text-xs text-muted-foreground">{asset.plant??"—"}</td><td className="px-4 py-3 text-xs font-semibold">{asset.company_code??"—"}</td><td className="px-4 py-3 text-xs text-muted-foreground">{asset.asset_categories?.name??"—"}</td><td className="px-4 py-3 text-xs text-muted-foreground">{asset.locations?.name??"—"}</td><td className="px-4 py-3 text-xs text-muted-foreground">{formatDate(assetStartDate(asset))}</td><td className="px-4 py-3 text-xs font-semibold">{formatAge(assetAgeMonths(asset))}</td><td className="px-4 py-3"><Status value={asset.status}/></td><td className="px-4 py-3 text-xs font-semibold">{money.format(Number(asset.purchase_value??0))}</td><td className="px-4 py-3 text-xs font-semibold">{money.format(Number(asset.current_value??0))}</td><td className="px-4 py-3">{onEdit ? <Button variant="ghost" size="icon" aria-label={`Edit ${asset.asset_id}`} title="Edit asset" onClick={event=>{event.stopPropagation();onEdit(asset)}}><Pencil className="size-4"/></Button> : <MoreHorizontal className="size-4 text-muted-foreground"/>}</td></tr>)}</tbody></table>{assets.length===0&&<div className="grid place-items-center p-14 text-sm text-muted-foreground">No assets match these filters.</div>}</div>}
function Status({value}:{value:string}){const cls=value==="active"||value==="assigned"?"bg-success/10 text-success":value.includes("maintenance")?"bg-warning/10 text-warning":value==="missing"?"bg-destructive/10 text-destructive":"bg-muted text-muted-foreground";return <span className={`inline-flex rounded-full px-2 py-1 text-[10px] font-bold ${cls}`}>{pretty(value)}</span>}

function Transfers({data,onNew}:{data:WorkspaceData;onNew:()=>void}){
  const client=useQueryClient();const [search,setSearch]=useState("");const [status,setStatus]=useState("all");
  const canManage=["super_admin","admin","asset_manager","facility_manager","it_manager"].includes(data.role);
  const locationName=(id:string|null)=>data.locations.find(item=>item.id===id)?.name??"Unassigned";
  const employeeName=(id:string|null)=>data.employees.find(item=>item.id===id)?.full_name??"Unassigned";
  const shown=data.transfers.filter(item=>(status==="all"||item.status===status)&&`${item.assets.asset_id} ${item.assets.name} ${item.reason}`.toLowerCase().includes(search.toLowerCase()));
  const action=useMutation({mutationFn:({id,next}:{id:string;next:"approve"|"reject"|"complete"})=>processTransfer({data:{transferId:id,action:next}}),onSuccess:async(result)=>{toast.success(`Transfer ${pretty(result.status??"updated")}`);await client.invalidateQueries({queryKey:["workspace"]})},onError:(error)=>toast.error(error.message)});
  const counts={pending:data.transfers.filter(item=>item.status==="pending").length,approved:data.transfers.filter(item=>item.status==="approved").length,completed:data.transfers.filter(item=>item.status==="completed").length};
  return <div className="space-y-5 soft-enter"><section className="grid gap-4 sm:grid-cols-3"><Kpi label="Pending" value={String(counts.pending)} delta="Awaiting approval" icon={Clock3} tone="warning"/><Kpi label="Approved" value={String(counts.approved)} delta="Ready to complete" icon={CheckCircle2} tone="primary"/><Kpi label="Completed" value={String(counts.completed)} delta="Assets moved" icon={ArrowRightLeft} tone="success"/></section><section className="glass-panel overflow-hidden rounded-2xl"><div className="flex flex-col gap-3 border-b border-white/60 p-4 md:flex-row md:items-center"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground"/><Input className="h-10 bg-white/60 pl-9" placeholder="Search asset ID, asset, or reason…" value={search} onChange={event=>setSearch(event.target.value)}/></div><Select value={status} onValueChange={setStatus}><SelectTrigger className="w-full bg-white/60 md:w-48" aria-label="Filter transfers by status"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem>{["pending","approved","completed","rejected","cancelled"].map(value=><SelectItem key={value} value={value}>{pretty(value)}</SelectItem>)}</SelectContent></Select>{canManage&&<Button variant="hero" onClick={onNew}><ArrowRightLeft/>New transfer</Button>}</div>{shown.length?<div className="grid gap-3 p-4 lg:grid-cols-2">{shown.map(item=><article key={item.id} className="rounded-xl border border-white/65 bg-white/35 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-xs font-bold text-primary">{item.assets.asset_id}</p><h2 className="mt-1 text-sm font-bold">{item.assets.name}</h2></div><Status value={item.status}/></div><div className="mt-4 grid grid-cols-[1fr_auto_1fr] items-center gap-3 rounded-lg bg-white/35 p-3"><div><p className="text-[10px] uppercase text-muted-foreground">From</p><p className="mt-1 text-xs font-semibold">{locationName(item.from_location_id)}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{employeeName(item.from_employee_id)}</p></div><ChevronRight className="size-4 text-primary"/><div><p className="text-[10px] uppercase text-muted-foreground">To</p><p className="mt-1 text-xs font-semibold">{locationName(item.to_location_id)}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{employeeName(item.to_employee_id)}</p></div></div><div className="mt-3 flex items-start justify-between gap-3 text-xs"><div><p className="font-semibold">{item.reason}</p><p className="mt-1 text-muted-foreground">Transfer date · {formatDate(item.transfer_date)}</p>{item.remarks&&<p className="mt-1 text-muted-foreground">{item.remarks}</p>}</div>{canManage&&["pending","approved"].includes(item.status)&&<DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" disabled={action.isPending}><MoreHorizontal/></Button></DropdownMenuTrigger><DropdownMenuContent align="end">{item.status==="pending"&&<DropdownMenuItem onClick={()=>action.mutate({id:item.id,next:"approve"})}><CheckCircle2/>Approve</DropdownMenuItem>}<DropdownMenuItem onClick={()=>action.mutate({id:item.id,next:"complete"})}><ArrowRightLeft/>Complete transfer</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem className="text-destructive" onClick={()=>action.mutate({id:item.id,next:"reject"})}><X/>Reject</DropdownMenuItem></DropdownMenuContent></DropdownMenu>}</div></article>)}</div>:<div className="grid min-h-64 place-items-center p-8 text-center"><div><ArrowRightLeft className="mx-auto size-9 text-muted-foreground"/><p className="mt-3 font-semibold">No transfers match this view</p><p className="mt-1 text-sm text-muted-foreground">Create a transfer to move an asset or change its custodian.</p>{canManage&&<Button className="mt-4" variant="hero" onClick={onNew}>New transfer</Button>}</div></div>}<div className="border-t border-white/60 p-4 text-xs text-muted-foreground">Showing {shown.length} of {data.transfers.length} transfers</div></section></div>;
}

function ModulePage({id,data}:{id:string;data:WorkspaceData}){if(id==="reports")return <Reports data={data}/>;if(id==="settings")return <SettingsPage data={data}/>;const rows=id==="categories"?data.categories:id==="locations"?data.locations:id==="employees"?data.employees:id==="transfers"?data.transfers:id==="maintenance"?data.maintenance:id==="verification"?data.verifications:[];return <div className="glass-panel rounded-2xl p-5 soft-enter"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display font-bold">{pageCopy[id]?.[0]}</h2><p className="mt-1 text-xs text-muted-foreground">Live organization records</p></div><Badge variant="outline">{rows.length} records</Badge></div>{rows.length?<div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row:any)=><div key={row.id} className="rounded-xl border border-white/65 bg-white/35 p-4"><div className="flex items-start justify-between"><div className="grid size-9 place-items-center rounded-lg bg-primary/10 text-primary">{id==="employees"?<UserRound className="size-4"/>:id==="locations"?<Building2 className="size-4"/>:<Archive className="size-4"/>}</div>{row.status&&<Status value={row.status}/>}</div><b className="mt-3 block text-sm">{row.name??row.full_name??row.title??row.assets?.name??`${pretty(id)} record`}</b><p className="mt-1 text-xs text-muted-foreground">{row.code??row.employee_code??row.reason??row.maintenance_type??row.assets?.asset_id??"Managed in Asset360"}</p></div>)}</div>:<EmptyModule id={id}/>}</div>}
function EmptyModule({id}:{id:string}){return <div className="grid min-h-72 place-items-center rounded-xl border border-dashed border-primary/20 bg-white/20 text-center"><div><CheckCircle2 className="mx-auto size-9 text-success"/><p className="mt-3 font-semibold">No {id} records yet</p><p className="mt-1 text-sm text-muted-foreground">Your workspace is clear and up to date.</p></div></div>}
function Reports({data}:{data:WorkspaceData}){const exportCsv=()=>{const escape=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;const headings=["Asset ID","Name","Serial Number","Plant","Company Code","Category","Location","Custodian","Installation Date","Age","Status","Condition","Acquisition Value","Book Value"];const rows=data.assets.map(a=>[a.asset_id,a.name,a.serial_number,a.plant,a.company_code,a.asset_categories?.name,a.locations?.name,a.employees?.full_name,formatDate(assetStartDate(a)),formatAge(assetAgeMonths(a)),a.status,a.condition,a.purchase_value,a.current_value]);const csv=[headings,...rows].map(row=>row.map(escape).join(",")).join("\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download="Sharvi-Asset360-Register.csv";link.click();URL.revokeObjectURL(link.href);toast.success("Asset register exported")};return <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><ReportCard title="Asset register" description="Complete portfolio with cost, age, location, and status." icon={Boxes} onClick={exportCsv}/><ReportCard title="Maintenance summary" description="Service workload and upcoming maintenance." icon={Wrench} onClick={exportCsv}/><ReportCard title="Verification status" description="Physical verification completion and exceptions." icon={ClipboardCheck} onClick={exportCsv}/></div>}
function ReportCard({title,description,icon:Icon,onClick}:{title:string;description:string;icon:any;onClick:()=>void}){return <button onClick={onClick} className="glass-panel rounded-2xl p-5 text-left transition hover:-translate-y-0.5"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Icon/></div><h2 className="mt-4 font-display font-bold">{title}</h2><p className="mt-1 text-sm text-muted-foreground">{description}</p><span className="mt-5 flex items-center gap-2 text-xs font-bold text-primary"><Download className="size-4"/>Download CSV</span></button>}
function SettingsPage({data}:{data:WorkspaceData}){return <div className="grid gap-5 xl:grid-cols-2"><div className="glass-panel rounded-2xl p-6"><h2 className="font-display font-bold">Organization</h2><div className="mt-5 space-y-4"><div><Label>Organization name</Label><Input className="mt-2 bg-white/55" value={data.organization?.name??""} readOnly/></div><div><Label>Deployment mode</Label><Input className="mt-2 bg-white/55 capitalize" value={data.organization?.mode??"standalone"} readOnly/></div></div></div><div className="glass-panel rounded-2xl p-6"><h2 className="font-display font-bold">ERP integration</h2><p className="mt-2 text-sm text-muted-foreground">SAP and ERP credentials stay server-side. This demo workspace runs independently.</p><div className="mt-5 flex items-center gap-3 rounded-xl bg-success/10 p-4 text-sm text-success"><ShieldCheck/>Secrets protected by server boundary</div><Button className="mt-5" variant="glass" onClick={()=>toast.info("ERP setup requires an administrator and server-side credentials")}>Configure integration</Button></div></div>}

function PageActions({active,setAssetDialog,assets,onImport,data}:{active:string;setAssetDialog:(v:boolean)=>void;assets:Asset[];onImport:()=>void;data:WorkspaceData}){
  const [downloading,setDownloading]=useState(false);
  const downloadTemplate=async()=>{setDownloading(true);try{await downloadAssetTemplate(data);}catch{toast.error("Could not download the Excel template. Please try again.");}finally{setDownloading(false);}};
  const exportAssets=()=>{const escape=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;const headings=["Asset ID","Name","Serial Number","Plant","Company Code","Status","Acquisition Value","Book Value"];const rows=assets.map(a=>[a.asset_id,a.name,a.serial_number,a.plant,a.company_code,a.status,a.purchase_value,a.current_value]);const blob=new Blob([[headings,...rows].map(row=>row.map(escape).join(",")).join("\n")],{type:"text/csv;charset=utf-8"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="asset360-assets.csv";link.click();URL.revokeObjectURL(link.href);};
  if(active==="assets") return <div className="flex flex-wrap gap-2"><Button variant="glass" onClick={exportAssets}><Download/>Export</Button><Button variant="outline" onClick={downloadTemplate} disabled={downloading}>{downloading?<LoaderCircle className="animate-spin"/>:<FileSpreadsheet/>}Download Excel template</Button><Button variant="outline" onClick={onImport}><Upload/>Upload Excel</Button><Button variant="hero" onClick={()=>setAssetDialog(true)}><PackagePlus/>Add asset</Button></div>;
  if(active==="dashboard") return <Button variant="hero" onClick={()=>setAssetDialog(true)}><PackagePlus/>Add asset</Button>;
  return <Button variant="glass" onClick={()=>toast.info(`${pageCopy[active]?.[0]??"This area"} is ready for organization records`)}><Download/>Export view</Button>;
}

function MobileNav({active,setActive}:{active:string;setActive:(id:string)=>void}){const items=nav.slice(0,5);return <nav className="glass-strong fixed inset-x-3 bottom-3 z-40 flex h-16 items-center justify-around rounded-2xl px-1 lg:hidden">{items.map(item=><Button key={item.id} variant="ghost" size="sm" onClick={()=>setActive(item.id)} className={`h-12 flex-col gap-1 px-3 text-[10px] ${active===item.id?"bg-primary/10 text-primary":"text-muted-foreground"}`}><item.icon className="size-4"/>{item.label}</Button>)}</nav>}

function CreateTransferDialog({open,setOpen,data}:{open:boolean;setOpen:(value:boolean)=>void;data:WorkspaceData}){
  const client=useQueryClient();const [form,setForm]=useState({assetId:"",toLocationId:"",toEmployeeId:"none",transferDate:new Date().toISOString().slice(0,10),reason:"",remarks:""});
  const asset=data.assets.find(item=>item.id===form.assetId);const set=(key:string,value:string)=>setForm(current=>({...current,[key]:value}));
  const mutation=useMutation({mutationFn:()=>createTransfer({data:{assetId:form.assetId,toLocationId:form.toLocationId,toEmployeeId:form.toEmployeeId==="none"?undefined:form.toEmployeeId,transferDate:form.transferDate,reason:form.reason,remarks:form.remarks||undefined}}),onSuccess:async()=>{toast.success("Transfer submitted for approval");setOpen(false);setForm(current=>({...current,assetId:"",toLocationId:"",toEmployeeId:"none",reason:"",remarks:""}));await client.invalidateQueries({queryKey:["workspace"]})},onError:(error)=>toast.error(error.message)});
  return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="glass-strong max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-xl">New asset transfer</DialogTitle><DialogDescription>Move an asset to another location or assign it to a new custodian.</DialogDescription></DialogHeader><form onSubmit={(event)=>{event.preventDefault();mutation.mutate()}}><div className="grid gap-4 py-4 sm:grid-cols-2"><Field label="Asset"><Select value={form.assetId} onValueChange={value=>set("assetId",value)} required><SelectTrigger><SelectValue placeholder="Select asset"/></SelectTrigger><SelectContent>{data.assets.map(item=><SelectItem key={item.id} value={item.id}>{item.asset_id} · {item.name}</SelectItem>)}</SelectContent></Select></Field><Field label="Transfer date"><Input type="date" value={form.transferDate} onChange={event=>set("transferDate",event.target.value)} required/></Field>{asset&&<div className="rounded-xl bg-white/35 p-4 sm:col-span-2"><p className="text-[10px] font-semibold uppercase text-muted-foreground">Current assignment</p><div className="mt-2 flex flex-wrap gap-x-6 gap-y-2 text-sm"><span><Building2 className="mr-1 inline size-4 text-primary"/>{asset.locations?.name??"No location"}</span><span><UserRound className="mr-1 inline size-4 text-primary"/>{asset.employees?.full_name??"Unassigned"}</span></div></div>}<Field label="Destination location"><Select value={form.toLocationId} onValueChange={value=>set("toLocationId",value)} required><SelectTrigger><SelectValue placeholder="Select destination"/></SelectTrigger><SelectContent>{data.locations.map(item=><SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}</SelectContent></Select></Field><Field label="New custodian"><Select value={form.toEmployeeId} onValueChange={value=>set("toEmployeeId",value)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Unassigned</SelectItem>{data.employees.filter(item=>item.status==="active").map(item=><SelectItem key={item.id} value={item.id}>{item.full_name} · {item.employee_code}</SelectItem>)}</SelectContent></Select></Field><Field label="Reason"><Input value={form.reason} onChange={event=>set("reason",event.target.value)} minLength={3} maxLength={200} placeholder="Relocation, reassignment, project need…" required/></Field><Field label="Remarks"><Input value={form.remarks} onChange={event=>set("remarks",event.target.value)} maxLength={1000}/></Field></div><DialogFooter><Button type="button" variant="ghost" onClick={()=>setOpen(false)}>Cancel</Button><Button type="submit" variant="hero" disabled={mutation.isPending||!form.assetId||!form.toLocationId}>{mutation.isPending&&<LoaderCircle className="animate-spin"/>}Submit transfer</Button></DialogFooter></form></DialogContent></Dialog>;
}
function Field({label,children}:{label:string;children:ReactNode}){return <div><Label className="mb-2 block">{label}</Label>{children}</div>}

function AssetDetail({asset,onClose,onEdit}:{asset:Asset|null;onClose:()=>void;onEdit:(asset:Asset)=>void}){const [labelsOpen,setLabelsOpen]=useState(false);return <Sheet open={Boolean(asset)} onOpenChange={open=>!open&&onClose()}><SheetContent className="app-backdrop w-full overflow-y-auto sm:max-w-lg"><SheetHeader><SheetTitle className="font-display text-xl">Asset details</SheetTitle></SheetHeader>{asset&&<div className="mt-6 space-y-5"><div className="glass-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><p className="font-mono text-xs font-bold text-primary">{asset.asset_id}</p><h2 className="mt-1 font-display text-xl font-bold">{asset.name}</h2><p className="mt-1 text-sm text-muted-foreground">{asset.manufacturer} {asset.model}</p></div><Status value={asset.status}/></div><div className="mt-5 grid grid-cols-2 gap-4 text-sm"><Info label="Category" value={asset.asset_categories?.name}/><Info label="Serial number" value={asset.serial_number}/><Info label="Plant" value={asset.plant}/><Info label="Company code" value={asset.company_code}/><Info label="Location" value={asset.locations?.name}/><Info label="Department" value={asset.departments?.name}/><Info label="Custodian" value={asset.employees?.full_name}/><Info label="Condition" value={pretty(asset.condition)}/><Info label="Installation date" value={formatDate(assetStartDate(asset))}/><Info label="Equipment age" value={formatAge(assetAgeMonths(asset))}/><Info label="Acquisition value" value={money.format(Number(asset.purchase_value??0))}/><Info label="Book value" value={money.format(Number(asset.current_value??0))}/></div></div><Button variant="outline" className="w-full" onClick={()=>onEdit(asset)}><Pencil/>Edit asset</Button><Button variant="hero" className="w-full" onClick={()=>setLabelsOpen(true)}><QrCode/>QR label</Button><LabelDialog open={labelsOpen} onOpenChange={setLabelsOpen} assets={[asset]} organization={asset.company_code??"Sharvi Asset360"}/></div>}</SheetContent></Sheet>}
function Info({label,value}:{label:string;value:string|null|undefined}){return <div><p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-1 font-medium">{value||"—"}</p></div>}


function pretty(value:string){return value.replaceAll("_"," ").replace(/\b\w/g,char=>char.toUpperCase())}
